27	//
28	// Tests that need a real process invoke the test binary itself with
29	// GO_WANT_HELPER_PROCESS=1 and -test.run=TestHelperProcess.
30	// The subprocess then acts as a minimal llama-server on the requested port.
31	//
32	// Supported extra flags (after "--"):
33	//   --health-delay-ms=N   delay GET /health by N milliseconds before responding 200
34	//   --fail                exit immediately without starting the HTTP server
35	// ---------------------------------------------------------------------------
36	
37	// TestHelperProcess is NOT a real test — it is a subprocess target.
38	func TestHelperProcess(t *testing.T) {
39		if os.Getenv("GO_WANT_HELPER_PROCESS") != "1" {
40			return
41		}
42	
43		// Locate args after "--"
44		args := os.Args
45		for i, a := range args {
46			if a == "--" {
47				args = args[i+1:]
48				break
49			}
50		}
51	
52		if len(args) == 0 || args[0] != "llama-server" {
53			fmt.Fprintln(os.Stderr, "expected llama-server as first arg")
54			os.Exit(2)
55		}
56	
57		// Parse flags from remaining args.
58		port := "8080"
59		healthDelayMs := 0
60		fail := false
61		for i, a := range args[1:] {
62			if a == "--port" && i+1 < len(args[1:]) {
63				port = args[1:][i+1]
64			}
65			if strings.HasPrefix(a, "--health-delay-ms=") {
66				ms, _ := strconv.Atoi(strings.TrimPrefix(a, "--health-delay-ms="))
67				healthDelayMs = ms
68			}
69			if a == "--fail" {
70				fail = true
71			}
72		}
73	
74		if fail {
75			os.Exit(1)
76		}
77	
78		mux := http.NewServeMux()
79		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
80			if healthDelayMs > 0 {
81				time.Sleep(time.Duration(healthDelayMs) * time.Millisecond)
82			}
83			w.WriteHeader(http.StatusOK)
84		})
85	
86		// Use port 0 to let the OS pick a free port, then print the listening
87		// line that wire's event parser expects.
88		listener, err := net.Listen("tcp", ":"+port)
89		if err != nil {
90			fmt.Fprintf(os.Stderr, "listen: %v\n", err)
91			os.Exit(2)
92		}
93		actualPort := listener.Addr().(*net.TCPAddr).Port
94		fmt.Fprintf(os.Stdout, "main: server is listening on http://127.0.0.1:%d\n", actualPort)
95	
96		srv := &http.Server{Handler: mux}
97		go srv.Serve(listener) //nolint:errcheck
98	
99		sigCh := make(chan os.Signal, 1)
100		signal.Notify(sigCh, syscall.SIGTERM, syscall.SIGINT)
101		<-sigCh
102	
103		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
104		defer cancel()
105		srv.Shutdown(ctx) //nolint:errcheck
106		os.Exit(0)
107	}
