157	// loadOrGetWait is a test helper that calls LoadOrGet and blocks until the
158	// ticket resolves or ctx is cancelled, mimicking the old synchronous signature.
159	func loadOrGetWait(ctx context.Context, m *Manager, modelName string, params config.ModelParams) (addr string, release func(), err error) {
160		ticket := m.LoadOrGet(modelName, params)
161		select {
162		case a, ok := <-ticket.Ready():
163			if !ok {
164				return "", func() {}, ticket.Err()
