382	// TestLoadOrGet_Coalescing verifies that 10 concurrent requests for the same
383	// unloaded model coalesce to a single process start.
384	func TestLoadOrGet_Coalescing(t *testing.T) {
385		cfg := &config.Config{
386			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
387			MaxModels: 1,
388		}
389		m := New(cfg, slog.Default())
390		// 200 ms startup delay to ensure all goroutines arrive before healthy.
391		m.cmdBuilder = testCmdBuilderWithDelay(200)
392	
393		ctx, cancel := context.WithCancel(context.Background())
394		defer cancel()
395		if err := m.Start(ctx); err != nil {
396			t.Fatalf("Start: %v", err)
397		}
398	
399		params := config.ModelParams{Slots: 1}
400		const n = 10
401		addrs := make([]string, n)
402		var wg sync.WaitGroup
403		wg.Add(n)
404		for i := range n {
405			go func(i int) {
406				defer wg.Done()
407				addr, release, err := loadOrGetWait(ctx, m, "org/model-a", params)
408				if err != nil {
409					t.Errorf("goroutine %d: LoadOrGet error: %v", i, err)
410					return
411				}
412				defer release()
413				addrs[i] = addr
414			}(i)
415		}
416		wg.Wait()
417	
418		// All goroutines must have gotten a non-empty addr.
419		first := addrs[0]
420		if first == "" {
421			t.Fatal("got empty addr")
422		}
423		for i, a := range addrs {
424			if a != first {
425				t.Errorf("goroutine %d: got addr %q, want %q (coalescing failed)", i, a, first)
426			}
427		}
428	
429		// Only one process should have been started.
430		if len(m.RunningModels()) != 1 {
431			t.Errorf("RunningModels: expected 1, got %d", len(m.RunningModels()))
432		}
433	}
