908		// Inject a synthetic proc in stateUnloading to verify that new requests
909		// to a draining model are rejected without waiting.
910		m.mu.Lock()
911		synth := &procState{
912			modelName: "org/draining",
913			state:     stateUnloading,
914			ready:     make(chan struct{}),
915			cancel:    func() {},
916		}
917		m.procs["org/draining"] = synth
918		m.mu.Unlock()
919	
920		tick := m.LoadOrGet("org/draining", config.ModelParams{})
921		select {
922		case _, ok := <-tick.Ready():
923			if ok {
924				t.Error("expected failure for unloading model, got address")
925				tick.Release()
926			}
927		case <-time.After(200 * time.Millisecond):
928			t.Error("ticket for draining model should fail immediately")
929		}
930		if tick.Err() == nil {
931			t.Error("expected non-nil error for unloading model")
932		}
933	
934		// Verify drainAndCancel respects the timeout: create a proc with inflight=1
935		// and confirm cancel() is called after drainTimeout.
936		ps2 := &procState{modelName: "org/timeout-test", cancel: func() {}}
937		ps2.inflight.Add(1)
938		start := time.Now()
939		m.drainTimeout = 100 * time.Millisecond
940		m.drainAndCancel(ps2)
941		elapsed := time.Since(start)
942		if elapsed < 90*time.Millisecond {
943			t.Errorf("drainAndCancel returned in %v; expected to wait ~100ms for timeout", elapsed)
944		}
945	}
946	
947	// TestLoadOrGet_CascadingVRAMEviction verifies that when VRAM is insufficient
948	// for a new model, the minimum set of LRU idle models is evicted to make room.
949	// Models A and B are loaded without a VRAM tracker. Then a tracker is attached
950	// with a mock backend that reports only 2 GiB free, less than model-c's 3 GiB
951	// estimate. The cascading eviction must select model-a (LRU) and leave model-b.
952	func TestLoadOrGet_CascadingVRAMEviction(t *testing.T) {
953		const (
954			totalVRAM = 8 << 30 // 8 GiB total
955			modelEst  = 3 << 30 // 3 GiB per model
956			// mock backend reports 6 GiB used → 2 GiB free (not enough for model-c)
957			mockUsed = 6 << 30
958		)
959	
960		cfg := &config.Config{
961			Models: map[string]config.ModelParams{
962				"org/model-a": {Slots: 1},
963				"org/model-b": {Slots: 1},
964				"org/model-c": {Slots: 1},
965			},
966			MaxModels: 10, // no count-based limit; only VRAM drives eviction
967		}
968	
969		m := newTestManager(cfg)
970	
971		bgCtx, cancel := context.WithCancel(context.Background())
972		defer cancel()
973		if err := m.Start(bgCtx); err != nil {
974			t.Fatalf("Start: %v", err)
975		}
976	
977		// Load model-a first (becomes LRU candidate) — no tracker yet.
978		_, releaseA, err := loadOrGetWait(bgCtx, m, "org/model-a", cfg.Models["org/model-a"])
979		if err != nil {
980			t.Fatalf("LoadOrGet model-a: %v", err)
981		}
982		releaseA()
983	
984		// Load model-b (more recently used) — still no tracker.
985		_, releaseB, err := loadOrGetWait(bgCtx, m, "org/model-b", cfg.Models["org/model-b"])
986		if err != nil {
987			t.Fatalf("LoadOrGet model-b: %v", err)
988		}
989		releaseB()
990	
991		// Now attach a VRAM tracker. The mock backend reports 6 GiB used, leaving
992		// only 2 GiB free — insufficient for model-c (3 GiB estimate).
993		backend := &mockVRAMBackend{total: totalVRAM, used: mockUsed}
994		tracker := vram.New(backend, nil)
995		tracker.Discover()
996		tracker.SetEstimate("org/model-a", modelEst)
997		tracker.SetEstimate("org/model-b", modelEst)
998		tracker.SetEstimate("org/model-c", modelEst)
999		m.SetVRAMTracker(tracker)
1000	
1001		// Request model-c: 3 GiB needed, only 2 GiB free → must evict model-a (LRU).
1002		_, releaseC, err := loadOrGetWait(bgCtx, m, "org/model-c", cfg.Models["org/model-c"])
1003		if err != nil {
1004			t.Fatalf("LoadOrGet model-c: %v", err)
1005		}
1006		releaseC()
1007	
1008		if m.Loaded("org/model-a") {
1009			t.Error("model-a should have been evicted (LRU)")
1010		}
1011		if !m.Loaded("org/model-b") {
1012			t.Error("model-b should still be loaded (more recently used)")
1013		}
1014		if !m.Loaded("org/model-c") {
1015			t.Error("model-c should be loaded")
1016		}
1017	}
1018	
1019	// ---------------------------------------------------------------------------
1020	// Helpers
1021	// ---------------------------------------------------------------------------
1022	
1023	// waitLoadedModel polls until the named model is healthy or the deadline passes.
1024	func waitLoadedModel(t *testing.T, m *Manager, name string, timeout time.Duration) {
1025		t.Helper()
1026		deadline := time.Now().Add(timeout)
1027		for time.Now().Before(deadline) {
1028			if m.Loaded(name) {
1029				return
1030			}
1031			time.Sleep(100 * time.Millisecond)
1032		}
1033		t.Fatalf("model %q did not become healthy within %v", name, timeout)
1034	}
