92	// New creates a Gateway backed by the given process manager.
93	// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
94	// remote may be nil; when non-nil, remote provider requests are tracked.
95	func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
