103	func newGateway(cfg *config.Config, mgr processManager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
104		// Build affinity table from warmup models.
105		modelSlots := make(map[string]int, len(cfg.Warmup))
106		for _, name := range cfg.Warmup {
107			if params, ok := cfg.MatchModel(name); ok {
108				modelSlots[name] = params.Slots
109			}
110		}
111	
112		g := &Gateway{mgr: mgr, log: log, affinity: newAffinityTable(modelSlots), remote: remote, discovery: discovery}
113		g.cfg.Store(cfg)
114	
115		qDepth := cfg.QueueDepth
116		if qDepth <= 0 {
117			qDepth = 200
118		}
119		g.q = queue.New(qDepth, func(ctx context.Context, model string) (string, func(), error) {
120			params, ok := g.cfg.Load().MatchModel(model)
121			if !ok {
122				return "", nil, fmt.Errorf("unknown model: %s", model)
123			}
124			t := g.mgr.LoadOrGet(model, params)
125			select {
126			case addr, ok := <-t.Ready():
127				if !ok {
128					return "", nil, t.Err()
129				}
130				return addr, t.Release, nil
131			case <-ctx.Done():
132				// Drain in background so the manager's in-flight counter stays consistent.
133				go func() {
134					if _, ok := <-t.Ready(); ok {
135						t.Release()
136					}
137				}()
138				return "", nil, ctx.Err()
139			}
140		})
141	
142		// Store hub as nctxProvider nil-safely: a nil *monitor.Hub must not become
143		// a non-nil interface value, which would cause g.hub == nil checks to fail.
144		if hub != nil {
145			g.hub = hub
146		}
