148		mux := http.NewServeMux()
149		mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
150		mux.HandleFunc("POST /v1/completions", g.handleRoute)
151		mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
152		mux.HandleFunc("POST /v1/rerank", g.handleRoute)
153		mux.HandleFunc("GET /v1/models", g.handleModels)
154		mux.HandleFunc("GET /health", g.handleHealth)
155	
156		if hub != nil {
157			mux.HandleFunc("GET /monitor", monitor.HandlePage)
158			mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
159		}
