165	// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
166	func (g *Gateway) ListenAndServe(ctx context.Context) error {
167		errCh := make(chan error, 1)
168		go func() {
169			if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
170				errCh <- err
171			}
172		}()
173		select {
174		case err := <-errCh:
175			return err
176		case <-ctx.Done():
177			shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
178			defer cancel()
179			return g.server.Shutdown(shutCtx)
