189	// Warmup submits each model in cfg.Warmup through the gateway's admission
190	// queue in config order. Each model is attempted up to warmupMaxAttempts times;
191	// if VRAM or capacity is insufficient, the attempt is retried after a delay.
192	// A warning is logged for any model that fails all attempts; startup continues.
193	// Warmup runs until all models are processed or ctx is cancelled.
194	func (g *Gateway) Warmup(ctx context.Context) {
195		interval := g.warmupInterval
196		if interval == 0 {
197			interval = warmupRetryInterval
198		}
199		for _, model := range g.cfg.Load().Warmup {
200			if ctx.Err() != nil {
