206	
207	func (g *Gateway) warmupOne(ctx context.Context, model string, retryInterval time.Duration) {
208		var lastErr error
209		for attempt := 1; attempt <= warmupMaxAttempts; attempt++ {
210			if attempt > 1 {
211				select {
212				case <-time.After(retryInterval):
213				case <-ctx.Done():
214					return
215				}
216			}
217	
218			ticket := g.q.Enqueue(model, queue.PriorityHigh, ctx)
219			select {
220			case _, ok := <-ticket.Ready():
221				if ok {
222					ticket.Release()
223					g.log.Info("warmup model loaded", "model", model, "attempt", attempt)
224					return
225				}
226				lastErr = ticket.Err()
227			case <-ctx.Done():
228				return
229			}
230	
231			if !isWarmupRetryable(lastErr) {
232				break
233			}
234			g.log.Warn("warmup model load attempt failed",
235				"model", model, "attempt", attempt, "max_attempts", warmupMaxAttempts, "error", lastErr)
236		}
237		g.log.Warn("warmup model failed to load after all attempts",
238			"model", model, "attempts", warmupMaxAttempts, "error", lastErr)
239	}
240	
241	func isWarmupRetryable(err error) bool {
242		if err == nil {
243			return false
244		}
245		return errors.Is(err, queue.ErrQueueFull) ||
246			errors.Is(err, queue.ErrModelEvicted) ||
247			errors.Is(err, process.ErrModelDraining) ||
248			errors.Is(err, context.DeadlineExceeded)
249	}
250	
251	// handleRoute extracts the model field from the JSON body and proxies to the matching process.
252	// If the model is known but not loaded, it is started on demand; the HTTP connection
253	// is held open until the model becomes healthy.
254	func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
255		// Read body once for all operations: model extraction, token estimation, slot affinity.
256		allBody, err := io.ReadAll(r.Body)
257		if err != nil {
258			writeError(w, http.StatusBadRequest, "invalid_request_error", "failed to read body", "bad_request")
259			return
260		}
261	
262		var payload struct {
263			Model string `json:"model"`
264		}
265		if err := json.Unmarshal(allBody, &payload); err != nil {
266			writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
267			return
268		}
269		if payload.Model == "" {
270			writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
271			return
272		}
273	
274		currentCfg := g.cfg.Load()
275		params, ok := currentCfg.MatchModel(payload.Model)
276		var snap monitor.DiscoverySnapshot
277		if !ok && g.discovery != nil {
278			snap = g.discovery.Snapshot()
279			if dm, found := snap.Lookup(payload.Model); found {
280				if _, provOk := currentCfg.Providers[dm.Provider]; provOk {
281					params = config.ModelParams{Provider: dm.Provider}
282					ok = true
283				}
284			}
285		}
286		if !ok {
287			writeError(w, http.StatusNotFound, "invalid_request_error", "unknown model: "+payload.Model, "model_not_found")
288			return
289		}
290	
291		if params.IsRemote() {
292			g.handleRemote(w, r, payload.Model, params, currentCfg, allBody)
293			return // handleRemote handles body rewrite if needed
294		}
295	
296		prio := pathPriority(r.URL.Path)
297		ticket := g.q.Enqueue(payload.Model, prio, r.Context())
298		var addr string
299		select {
300		case a, ok := <-ticket.Ready():
301			if !ok {
302				err := ticket.Err()
303				switch {
304				case errors.Is(err, queue.ErrQueueFull):
305					w.Header().Set("Retry-After", "5")
306					writeError(w, http.StatusServiceUnavailable, "server_error", "queue at capacity", "queue_full")
307				case errors.Is(err, queue.ErrModelEvicted), errors.Is(err, process.ErrModelDraining):
308					w.Header().Set("Retry-After", "10")
309					writeError(w, http.StatusServiceUnavailable, "server_error", "model unavailable, retry later", "model_draining")
310				case errors.Is(err, context.DeadlineExceeded):
311					writeError(w, http.StatusGatewayTimeout, "server_error", "model load timed out", "load_timeout")
312				default:
313					writeError(w, http.StatusServiceUnavailable, "server_error", err.Error(), "model_not_loaded")
314				}
315				return
316			}
317			addr = a
318		case <-r.Context().Done():
319			writeError(w, http.StatusServiceUnavailable, "server_error", "request cancelled", "request_cancelled")
320			return
321		}
322		defer ticket.Release()
323	
324		if g.hub != nil {
325			if nCtx := g.hub.NCtx(payload.Model); nCtx > 0 {
326				if est := estimateTokens(allBody); est > 0 && est > nCtx*9/10 {
327					writeError(w, http.StatusBadRequest, "invalid_request_error",
328						fmt.Sprintf("estimated %d tokens exceeds context window of %d (n_ctx)", est, nCtx),
329						"context_length_exceeded")
330					return
331				}
332			}
333		}
334	
335		g.affinity.Register(payload.Model, params.Slots)
336	
337		hash := prefixHash(allBody)
338		if slotID, assigned := g.affinity.Assign(payload.Model, hash); assigned {
339			allBody = injectSlot(allBody, slotID)
340		}
341		r.Body = io.NopCloser(bytes.NewReader(allBody))
342		r.ContentLength = int64(len(allBody))
343	
344		target, parseErr := url.Parse(addr)
345		if parseErr != nil {
346			writeError(w, http.StatusInternalServerError, "server_error", "invalid backend URL", "internal_error")
347			return
348		}
349	
350		proxy := &httputil.ReverseProxy{
351			Rewrite: func(pr *httputil.ProxyRequest) {
352				pr.SetURL(target)
353				pr.Out.Host = target.Host
354			},
355			FlushInterval:  -1,
356			ModifyResponse: rewriteContextLengthError,
357			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
358				g.log.Error("proxy error", "model", payload.Model, "error", err)
359				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
360			},
361		}
362	
363		proxy.ServeHTTP(w, r)
364	}
365	
366	// handleModels returns all known models with their current status.
367	func (g *Gateway) handleModels(w http.ResponseWriter, _ *http.Request) {
368		type modelObj struct {
369			ID           string   `json:"id"`
370			Object       string   `json:"object"`
371			Type         string   `json:"type"`
372			Status       string   `json:"status,omitempty"`
373			Capabilities []string `json:"capabilities,omitempty"`
374			Provider     string   `json:"provider,omitempty"`
375		}
376		type modelsResp struct {
377			Object string     `json:"object"`
378			Data   []modelObj `json:"data"`
379		}
380	
381		models := g.Models()
382		data := make([]modelObj, 0, len(models))
383		for _, m := range models {
384			data = append(data, modelObj{
385				ID:           m.ID,
386				Object:       m.Object,
387				Type:         m.Type,
388				Status:       m.Status,
389				Capabilities: m.Capabilities,
390				Provider:     m.Provider,
391			})
392		}
393	
394		w.Header().Set("Content-Type", "application/json")
395		json.NewEncoder(w).Encode(modelsResp{Object: "list", Data: data}) //nolint:errcheck
396	}
397	
398	// Models returns all known models as ModelInfo slice.
399	func (g *Gateway) Models() []monitor.ModelInfo {
400		cfg := g.cfg.Load()
401		var models []monitor.ModelInfo
402	
403		// Local models from Manager (loaded/running)
404		localModels := g.mgr.ListModels()
405		for _, mi := range localModels {
406			obj := monitor.ModelInfo{
407				ID:     mi.ID,
408				Object: "model",
409				Type:   "local",
410				Status: mi.Status,
411			}
412			if p, ok := cfg.MatchModel(mi.ID); ok {
413				obj.Capabilities = p.Capabilities
414			}
415			models = append(models, obj)
416		}
417	
418		listed := make(map[string]bool, len(models))
419		for _, m := range models {
420			listed[m.ID] = true
421		}
422	
423		// HF cache models (local but not loaded)
424		for _, cm := range g.scanHFCache() {
425			if listed[cm] {
426				continue
427			}
428			models = append(models, monitor.ModelInfo{
429				ID:     cm,
430				Object: "model",
431				Type:   "local",
432				Status: "available",
433			})
434			listed[cm] = true
435		}
436	
437		// Configured remote models
438		configuredRemote := make(map[string]bool)
439		for pattern, p := range cfg.Models {
440			if !p.IsRemote() {
441				continue
442			}
443			configuredRemote[pattern] = true
444			models = append(models, monitor.ModelInfo{
445				ID:           pattern,
446				Object:       "model",
447				Type:         "remote",
448				Status:       "available",
449				Capabilities: p.Capabilities,
450				Provider:     p.Provider,
451			})
452		}
453	
454		// Discovered remote models
455		if g.discovery != nil {
456			for _, dm := range g.discovery.Snapshot().AllModels() {
457				if configuredRemote[dm.ID] {
458					continue
459				}
460				models = append(models, monitor.ModelInfo{
461					ID:       dm.ID,
462					Object:   "model",
463					Type:     "remote",
464					Status:   "available",
465					Provider: dm.Provider,
466				})
467			}
468		}
469	
470		return models
471	}
472	
473	// handleHealth returns 200 if at least one warmup model is healthy, 503 otherwise.
474	func (g *Gateway) handleHealth(w http.ResponseWriter, _ *http.Request) {
475		w.Header().Set("Content-Type", "application/json")
476		if slices.ContainsFunc(g.cfg.Load().Warmup, g.mgr.Loaded) {
477			w.WriteHeader(http.StatusOK)
478			json.NewEncoder(w).Encode(map[string]string{"status": "ok"}) //nolint:errcheck
479			return
480		}
481		w.WriteHeader(http.StatusServiceUnavailable)
482		json.NewEncoder(w).Encode(map[string]string{"status": "degraded"}) //nolint:errcheck
483	}
484	
485	// handleRemote proxies a request to a remote OpenAI-compatible provider,
486	// bypassing the process manager entirely. body may be rewound if upstream_model rewrite is needed.
487	func (g *Gateway) handleRemote(w http.ResponseWriter, r *http.Request, modelName string, params config.ModelParams, cfg *config.Config, body []byte) {
488		provider, ok := cfg.Providers[params.Provider]
489		if !ok {
490			writeError(w, http.StatusInternalServerError, "server_error", "unknown provider: "+params.Provider, "config_error")
491			return
492		}
493	
494		if params.UpstreamModel != "" {
495			var obj map[string]json.RawMessage
496			if err := json.Unmarshal(body, &obj); err == nil {
497				if raw, err := json.Marshal(params.UpstreamModel); err == nil {
498					obj["model"] = raw
499					if rewritten, err := json.Marshal(obj); err == nil {
500						body = rewritten
501					}
502				}
503			}
504		}
505		r.Body = io.NopCloser(bytes.NewReader(body))
506		r.ContentLength = int64(len(body))
507	
508		baseTarget, err := url.Parse(provider.BaseURL)
509		if err != nil {
510			writeError(w, http.StatusInternalServerError, "server_error", "invalid provider URL", "config_error")
511			return
512		}
513	
514		apiKey := provider.APIKey
515		reqPath := r.URL.Path
516		upstreamModel := params.UpstreamModel
517		if upstreamModel == "" {
518			upstreamModel = modelName
519		}
520	
521		// Track remote request metrics.
522		var done func(int64, int)
523		if g.remote != nil {
524			done = g.remote.Start(modelName, params.Provider)
525		}
526		start := time.Now()
527	
528		proxy := &httputil.ReverseProxy{
529			Rewrite: func(pr *httputil.ProxyRequest) {
530				pr.SetURL(baseTarget)
531				pr.Out.URL.Path = baseTarget.Path + reqPath
532				pr.Out.Host = baseTarget.Host
533				pr.Out.Header.Set("Authorization", "Bearer "+apiKey)
534			},
535			FlushInterval: -1,
536			ModifyResponse: func(resp *http.Response) error {
537				resp.Header.Set("X-Wire-Model", upstreamModel)
538				if done != nil {
539					done(time.Since(start).Nanoseconds(), resp.StatusCode)
540					done = nil // prevent double-call
541				}
542				return rewriteContextLengthError(resp)
543			},
544			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
545				g.log.Error("remote proxy error", "model", modelName, "provider", params.Provider, "error", err)
546				if done != nil {
547					done(time.Since(start).Nanoseconds(), 502)
548					done = nil
549				}
550				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
551			},
552		}
553	
554		proxy.ServeHTTP(w, r)
555	}
556	
557	// estimateTokens approximates the token count of a request body using a
558	// chars/4 heuristic. It extracts text from messages[].content (chat) and the
559	// input field (embeddings). Returns 0 on parse failure or empty content.
560	func estimateTokens(body []byte) int {
561		var req struct {
562			Messages []struct {
563				Content json.RawMessage `json:"content"`
564			} `json:"messages"`
565			Input json.RawMessage `json:"input"`
566		}
567		if err := json.Unmarshal(body, &req); err != nil {
568			return 0
569		}
570	
571		total := 0
572		for _, msg := range req.Messages {
573			if len(msg.Content) == 0 {
574				continue
575			}
576			var s string
577			if err := json.Unmarshal(msg.Content, &s); err == nil {
578				total += len(s)
579				continue
580			}
581			var parts []struct {
582				Text string `json:"text"`
583			}
584			if err := json.Unmarshal(msg.Content, &parts); err == nil {
585				for _, p := range parts {
586					total += len(p.Text)
587				}
588			}
589		}
590	
591		if len(req.Input) > 0 {
592			var s string
593			if err := json.Unmarshal(req.Input, &s); err == nil {
594				total += len(s)
595			} else {
596				var arr []string
597				if err := json.Unmarshal(req.Input, &arr); err == nil {
598					for _, s := range arr {
599						total += len(s)
600					}
601				}
602			}
603		}
604	
605		return total / 4
606	}
607	
608	// rewriteContextLengthError inspects non-2xx upstream responses for a
609	// context_length_exceeded error code and rewrites the status to 400 to match
610	// the OpenAI API standard. llama-server returns these as 500.
611	func rewriteContextLengthError(resp *http.Response) error {
612		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
613			return nil
614		}
615	
616		body, err := io.ReadAll(resp.Body)
617		resp.Body.Close()
618		if err != nil {
619			resp.Body = io.NopCloser(bytes.NewReader(nil))
620			return nil
621		}
622	
623		var envelope struct {
624			Error struct {
625				Code string `json:"code"`
626			} `json:"error"`
627		}
628		if json.Unmarshal(body, &envelope) == nil && envelope.Error.Code == "context_length_exceeded" {
629			resp.StatusCode = http.StatusBadRequest
630			resp.Status = http.StatusText(http.StatusBadRequest)
631		}
632	
633		resp.Body = io.NopCloser(bytes.NewReader(body))
634		return nil
635	}
636	
637	const hfCacheTTL = 30 * time.Second
638	
639	// scanHFCache returns cached model IDs (org/repo:QUANT) for all GGUF files
640	// found in the HuggingFace hub cache. Results are cached for 30s to avoid
641	// repeated filesystem I/O on /v1/models calls.
642	func (g *Gateway) scanHFCache() []string {
643		if g.hfCacheDir == "" {
644			return nil
645		}
646		if ids, ok := g.hfCache.get(hfCacheTTL); ok {
647			return ids
648		}
649	
650		entries, err := os.ReadDir(g.hfCacheDir)
651		if err != nil {
652			return nil
653		}
654	
655		var models []string
656		for _, entry := range entries {
657			name := entry.Name()
658			if !entry.IsDir() || !strings.HasPrefix(name, "models--") {
659				continue
660			}
661			// models--org--repo → org/repo
662			parts := strings.SplitN(name, "--", 3)
663			if len(parts) != 3 {
664				continue
665			}
666			repo := parts[1] + "/" + parts[2]
667	
668			// Walk snapshots for .gguf files.
669			snapshotsDir := filepath.Join(g.hfCacheDir, name, "snapshots")
670			snapshots, err := os.ReadDir(snapshotsDir)
671			if err != nil {
672				continue
673			}
674			seen := make(map[string]bool)
675			for _, snap := range snapshots {
676				if !snap.IsDir() {
677					continue
678				}
679				ggufs, err := filepath.Glob(filepath.Join(snapshotsDir, snap.Name(), "*.gguf"))
680				if err != nil {
681					continue
682				}
683				for _, path := range ggufs {
684					base := strings.TrimSuffix(filepath.Base(path), ".gguf")
685					// Skip auxiliary files (e.g. mmproj-BF16.gguf).
686					if strings.HasPrefix(base, "mmproj") {
687						continue
688					}
689					// Extract quant: look for Q prefix after the last dash-or-dot, but handle
690					// compound quants like Q5_K_M. The pattern is: model-name[-size]Q<num>[_<variant>]
691					// e.g. "Qwen3-4B-Q8_0" → "Q8_0", "Qwen3-4B-Q5_K_M" → "Q5_K_M"
692					quant := extractQuant(base)
693					if quant == "" {
694						continue
695					}
696					id := repo + ":" + quant
697					if !seen[id] {
698						seen[id] = true
699						models = append(models, id)
700					}
701				}
702			}
703		}
704		g.hfCache.set(models, hfCacheTTL)
705		return models
706	}
707	
708	// extractQuant extracts the quantization suffix from a GGUF filename.
709	// Handles patterns like "Qwen3-4B-Q8_0", "Qwen3-4B-Q5_K_M", "Phi-4-mini-instruct.Q8_0".
710	// Returns empty string if no valid quant is found.
711	func extractQuant(base string) string {
712		// Find last Q<num> and stop at -XB boundary (e.g., -4B, -8B)
713		for i := len(base) - 1; i >= 0; i-- {
714			if i > 0 && base[i] == 'B' && base[i-1] >= '0' && base[i-1] <= '9' {
715				break
716			}
717			if i+1 < len(base) && base[i] == 'Q' && base[i+1] >= '0' && base[i+1] <= '9' {
718				return base[i:]
719			}
720		}
721		return ""
722	}
723	
724	// pathPriority maps a request path to a queue priority tier.
725	func pathPriority(path string) queue.Priority {
726		switch path {
727		case "/v1/completions":
728			return queue.PriorityMedium
729		case "/v1/embeddings", "/v1/rerank":
730			return queue.PriorityLow
731		default:
732			return queue.PriorityHigh
733		}
734	}
735	
736	// writeError writes an OpenAI-format JSON error response.
737	func writeError(w http.ResponseWriter, status int, errType, message, code string) {
738		w.Header().Set("Content-Type", "application/json")
739		w.WriteHeader(status)
740		json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
741			"error": map[string]any{
742				"message": message,
743				"type":    errType,
744				"code":    code,
745			},
746		})
747	}
748

